def market_states(path,decision_dates):
 x=pd.read_csv(path);x=x[x.asset.eq("equity")].copy();x.trade_date=pd.to_datetime(x.trade_date,format="mixed");x=x.sort_values("trade_date");x["sma200"]=x.adj_close.rolling(200,min_periods=200).mean();lookup=x.set_index("trade_date");return {date:bool(pd.Timestamp(date) in lookup.index and pd.notna(lookup.at[pd.Timestamp(date),"sma200"]) and float(lookup.at[pd.Timestamp(date),"adj_close"])>float(lookup.at[pd.Timestamp(date),"sma200"])) for date in decision_dates}
def yearly_return(returns,year):
 x=returns[pd.to_datetime(returns.index).year==year];return float((1+x).prod()-1) if len(x) else 0.0
def revision_breadth_states(signals,decision_dates):
 frame=signals.copy();frame["signal_date"]=pd.to_datetime(frame.signal_date);breadth=frame.groupby("signal_date").revision.apply(lambda values:float((values>0).mean()));states={}
 for date in sorted(decision_dates):
  day=pd.Timestamp(date);history=breadth[breadth.index<day].tail(24);states[date]=bool(len(history)==24 and day in breadth.index and float(breadth.loc[day])>float(history.median()))
 return states,breadth
def run(raw_dir,start,end,benchmark_path,signals_path,nav_path,out_json,out_md,current_json,current_md,gate_mode="market"):
 reports=load_reports(raw_dir);dates,lookup,targets,signals,metadata=build_inputs(start,end,reports,"revision");signals.to_csv(signals_path,index=False,date_format="%Y-%m-%d");states,breadth=(revision_breadth_states(signals,targets) if gate_mode=="revision_breadth" else (market_states(benchmark_path,targets),None));gated={date:(symbols if states[date] else []) for date,symbols in targets.items()};config=BasketConfig(name="market_gated_analyst_top30",target_count=30,initial_nav=400000,buy_cost=.00155,sell_cost=.00155);gross_config=BasketConfig(name="market_gated_analyst_top30_gross",target_count=30,initial_nav=400000,buy_cost=0,sell_cost=0);result=simulate_basket(dates,lookup,gated,config);gross=simulate_basket(dates,lookup,gated,gross_config);benchmark=benchmark_returns(benchmark_path,dates);portfolio=summarize_basket(result,gross,benchmark,config,folds=FOLDS);pd.DataFrame({"date":result.dates,"nav":result.nav,"gross_nav":gross.nav,"benchmark_return":benchmark.to_numpy()}).to_csv(nav_path,index=False);enabled=sum(states.values());participation=enabled/len(states);strategy_2025=float(portfolio["yearly_returns"].get("2025",0));benchmark_2025=yearly_return(benchmark,2025);checks={"cagr":portfolio["metrics"]["cagr"]>=.10,"excess":portfolio["excess_cagr"]>=.02,"sharpe":portfolio["metrics"]["sharpe"]>=.80,"drawdown":portfolio["metrics"]["max_drawdown"]>=-.30,"folds":all(value["excess_cagr"]>0 for value in portfolio["folds"].values()),"turnover":portfolio["annual_turnover"]<=10,"lots":portfolio["lot_failures"]==0,"cost_retention":portfolio["gross_to_net_cagr_retention"]>=.90,"holdout_2025":strategy_2025>0 and strategy_2025>benchmark_2025,"participation":.20<=participation<=.80};payload=json_clean({"study":"a-share-revision-regime-analyst-v11" if gate_mode=="revision_breadth" else "a-share-market-gated-analyst-v10","gate_mode":gate_mode,"authority":"exploratory_only_no_platform_prepare_operation","data":{**metadata,"market_gate":"positive revision share > prior-24-month median" if gate_mode=="revision_breadth" else "510300 close > inclusive SMA200","enabled_months":enabled,"decision_months":len(states),"participation":participation},"portfolio":portfolio,"holdout_2025":{"strategy_return":strategy_2025,"benchmark_return":benchmark_2025,"excess":strategy_2025-benchmark_2025},"checks":checks,"verdict":"GO" if all(checks.values()) else "NO-GO","signals":signals_path,"nav":nav_path,"trade_authorized":False});Path(out_json).write_text(json.dumps(payload,ensure_ascii=False,indent=2)+"\n");m=portfolio["metrics"];title="# A股修正广度状态分析师策略V11结果" if gate_mode=="revision_breadth" else "# A股市场状态条件化分析师策略V10结果";lines=[title,"",f"- verdict: **{payload['verdict']}**",f"- CAGR/Sharpe/MDD: {m['cagr']:.2%} / {m['sharpe']:.3f} / {m['max_drawdown']:.2%}",f"- excess CAGR/participation: {portfolio['excess_cagr']:.2%} / {participation:.2%}",f"- 2025 strategy/benchmark/excess: {strategy_2025:.2%} / {benchmark_2025:.2%} / {strategy_2025-benchmark_2025:.2%}"];Path(out_md).write_text("\n".join(lines)+"\n");last_decision=max(states);current={"as_of":end,"last_decision":last_decision,"market_enabled":states[last_decision],"target_count":len(gated[last_decision]),"targets":gated[last_decision],"strategy_verdict":payload["verdict"],"trade_authorized":False};Path(current_json).write_text(json.dumps(current,ensure_ascii=False,indent=2)+"\n");Path(current_md).write_text("# A股条件化分析师当前状态\n\n"+f"- as of: {end}\n- last decision: {last_decision}\n- market enabled: **{states[last_decision]}**\n- target count: {len(gated[last_decision])}\n- trade authorized: **NO**\n");print("\n".join(lines));return payload
def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument("--raw-dir",default="overall/a-share-report-rc-raw");p.add_argument("--start",default="2017-01-03");p.add_argument("--end",default="2026-08-26");p.add_argument("--benchmark",default="overall/a-share-equity-etf-daily-current.csv");p.add_argument("--signals",default="overall/a-share-market-gated-analyst-signals.csv");p.add_argument("--nav",default="overall/a-share-market-gated-analyst-nav.csv");p.add_argument("--out-json",default="overall/a-share-market-gated-analyst-v10-result.json");p.add_argument("--out-md",default="overall/a-share-market-gated-analyst-v10-result.md");p.add_argument("--current-json",default="overall/a-share-market-gated-analyst-current.json");p.add_argument("--current-md",default="overall/a-share-market-gated-analyst-current.md");p.add_argument("--gate-mode",choices=["market","revision_breadth"],default="market");a=p.parse_args(argv);run(a.raw_dir,a.start,a.end,a.benchmark,a.signals,a.nav,a.out_json,a.out_md,a.current_json,a.current_md,a.gate_mode);return 0
